CREATE TABLE IF NOT EXISTS schema_version(version INTEGER PRIMARY KEY);
INSERT OR IGNORE INTO schema_version VALUES(1);
CREATE TABLE IF NOT EXISTS admins(id TEXT PRIMARY KEY, username TEXT UNIQUE NOT NULL, hash TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token TEXT PRIMARY KEY, role TEXT NOT NULL, username TEXT NOT NULL, exam TEXT, expires INTEGER NOT NULL, csrf TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS exams(id TEXT PRIMARY KEY, config TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS enrollments(exam TEXT NOT NULL REFERENCES exams(id), username TEXT NOT NULL, webcam INTEGER, duration INTEGER, display_name TEXT, uid INTEGER NOT NULL, PRIMARY KEY(exam,username));
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY, exam TEXT NOT NULL REFERENCES exams(id), username TEXT NOT NULL, uid INTEGER NOT NULL, state TEXT NOT NULL, settings TEXT NOT NULL, start INTEGER, deadline INTEGER, ended INTEGER, generation INTEGER NOT NULL DEFAULT 0, page_hash TEXT, last_contact INTEGER, reason TEXT, work_path TEXT, export_status TEXT, checksum TEXT, UNIQUE(exam,username));
CREATE UNIQUE INDEX IF NOT EXISTS account_busy ON attempts(uid) WHERE state IN ('PREPARING','ACTIVE','LOCKED','FINALIZING','COLLECTION_FAILED');
CREATE TABLE IF NOT EXISTS incidents(id TEXT PRIMARY KEY, attempt TEXT NOT NULL REFERENCES attempts(id), generation INTEGER NOT NULL, opened INTEGER NOT NULL, events TEXT NOT NULL, message TEXT, review_at INTEGER, UNIQUE(attempt,generation));
CREATE TABLE IF NOT EXISTS continuations(attempt TEXT PRIMARY KEY REFERENCES attempts(id), generation INTEGER NOT NULL, expires INTEGER NOT NULL, consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS frames(id TEXT PRIMARY KEY, attempt TEXT NOT NULL REFERENCES attempts(id), source TEXT NOT NULL, seq INTEGER NOT NULL, page_hash TEXT NOT NULL, captured INTEGER NOT NULL, monotonic REAL NOT NULL, received INTEGER NOT NULL, width INTEGER NOT NULL, height INTEGER NOT NULL, hash TEXT NOT NULL, UNIQUE(attempt,source,seq,page_hash));
CREATE TABLE IF NOT EXISTS recordings(id TEXT PRIMARY KEY, attempt TEXT NOT NULL REFERENCES attempts(id), pane TEXT NOT NULL, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS previews(id TEXT PRIMARY KEY, exam TEXT NOT NULL, rows TEXT NOT NULL, created INTEGER NOT NULL, consumed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS outbox(id TEXT PRIMARY KEY, subject TEXT NOT NULL, body TEXT NOT NULL, tries INTEGER NOT NULL DEFAULT 0, next INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'pending');
CREATE TABLE IF NOT EXISTS audit(id TEXT PRIMARY KEY, at INTEGER NOT NULL, actor TEXT NOT NULL, action TEXT NOT NULL, target TEXT NOT NULL, detail TEXT);
CREATE TABLE IF NOT EXISTS tombstones(attempt TEXT PRIMARY KEY, deleted INTEGER NOT NULL);
